<div class="card"><h3>Workspace settings</h3><form data-api="admin/settings"><div class="form-grid"><?php field('site_name','Site name','text',setting('site_name','SEO AutoPilot'));field('contact_email','Contact email','email',setting('contact_email',''),false);field('crawl_delay_ms','Crawl delay (200–5000 ms)','number',setting('crawl_delay_ms',1000));foreach(['registration'=>'Allow registration','maintenance'=>'Maintenance mode','require_verification'=>'Require email verification'] as $k=>$v)select_field($k,$v,['1'=>'Enabled','0'=>'Disabled'],setting($k,false)?'1':'0');?></div><label>Score weights (JSON, total 100)<textarea name="score_weights"><?=e(json_encode(setting('score_weights'),JSON_PRETTY_PRINT))?></textarea></label><button class="button">Save settings</button></form></div><div class="card stack"><h3>Provider configuration</h3><p>Credentials are read from protected server configuration. Secret values are never returned to the browser.</p><?php table(['provider'=>'Provider','status'=>'Status'],[['provider'=>'AI endpoint / model','status'=>cfg('AI_API_KEY')&&cfg('AI_ENDPOINT')&&cfg('AI_MODEL')?'Configured':'Not configured'],['provider'=>'Razorpay','status'=>cfg('RAZORPAY_KEY')&&cfg('RAZORPAY_SECRET')&&cfg('RAZORPAY_WEBHOOK_SECRET')?'Configured':'Not configured'],['provider'=>'SMTP','status'=>cfg('SMTP_HOST')&&cfg('SMTP_FROM')?'Configured':'Not configured'],['provider'=>'Rankings','status'=>cfg('RANKING_ENDPOINT')&&cfg('RANKING_API_KEY')?'Configured':'Not configured']]);?></div><div class="card stack"><h3>Editable public policies & pages</h3><form data-api="admin/page"><?php select_field('page','Page',array_combine(['terms','privacy','refund-policy','cookie-policy','about','contact'],['Terms','Privacy','Refund policy','Cookie policy','About','Contact']));?><label>Page content (plain text)<textarea name="content" rows="12" required></textarea></label><button class="button">Publish page text</button></form></div><div class="card stack"><h3>Protected database export</h3><p>Exports contain personal data and password hashes. Save them in encrypted, access-controlled storage.</p><form method="post" action="<?=url('/api/v1/admin/backup')?>"><?php csrf_field();?><button class="button secondary">Download database SQL</button></form></div><?php require ROOT.'/admin/advanced.php';?>
